import backtrader as bt


class BuyingSpikeMomentum(bt.Strategy):
    def __init__(self):
        self.price_sma20 = bt.indicators.SMA(self.data.close, period=20)
        self.volume_sma5 = bt.indicators.SMA(self.data.volume, period=5)
        self.volume_sma20 = bt.indicators.SMA(self.data.volume, period=20)
        self.stochastic = bt.indicators.Stochastic(
            self.data,
            period=14,
            period_dfast=3,
            period_dslow=3,
        )
        self.stochastic_crossover = bt.indicators.CrossOver(
            self.stochastic.percK, self.stochastic.percD
        )
        self.atr14 = bt.indicators.ATR(self.data, period=14)

        self.order = None
        self.stop_order = None
        self.entry_bar = None

    def next(self):
        if self.order:
            return

        if not self.position:
            size = (self.broker.getvalue() * 0.02) / self.data.close[0]
            if (
                self.data.close[0] > self.price_sma20[0]
                and self.volume_sma5[0] >= 3.0 * self.volume_sma20[0]
                and self.stochastic.percK[0] > 80.0
                and (
                    self.stochastic_crossover[0] > 0.0
                    or self.data.close[0] > self.data.close[-1]
                )
                and self.atr14[0] / self.data.close[0] > 0.015
                and self.volume_sma20[0] * self.price_sma20[0] >= 10_000_000
            ):
                self.order = self.buy(size=size)
        elif (
            self.data.close[0] < self.price_sma20[0]
            or len(self) - self.entry_bar >= 10
        ):
            if self.stop_order:
                self.cancel(self.stop_order)
                self.stop_order = None
            self.order = self.close()

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.isbuy():
                self.entry_bar = len(self)
                self.stop_order = self.sell(
                    size=order.executed.size,
                    exectype=bt.Order.Stop,
                    price=order.executed.price * 0.98,
                )
            else:
                self.entry_bar = None
                if order is self.stop_order:
                    self.stop_order = None

            if order is self.order:
                self.order = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            if order is self.order:
                self.order = None
            if order is self.stop_order:
                self.stop_order = None
